eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   xiaohongshuContent: () => (/* binding */ xiaohongshuContent)\n/* harmony export */ });\nconst xiaohongshuContent = [\n    {\n        id: \"1\",\n        title: \"南宁凌晨1点宵夜地图！本地人私藏美食攻略\",\n        content: \"周五晚上凌晨一点落地南宁！！想逛一下夜市或者吃点南宁特色。这个点夜市还热闹吗？我的互联网姐妹们有什么推荐去的地方吗！！江南区黎塘六叔美食，在菜市场里面，大晚上从青秀山出来肚子饿扁，点了想吃好久的几道菜都没有踩雷的！最好吃的是香叶牛肉！看起来像树叶哈哈哈里面包着牛肉末炸得酥酥脆脆，蘸旁边的果酱更好吃了...\",\n        author: \"葡萄味冻冻\",\n        likes: 379,\n        collects: 286,\n        publishTime: \"2024-01-15\",\n        tags: [\n            \"南宁美食\",\n            \"宵夜地图\",\n            \"本地攻略\",\n            \"深夜食堂\"\n        ],\n        imageUrl: \"https://images.unsplash.com/photo-1565299624946-b28f40a0ca4b?w=400&h=300&fit=crop\",\n        location: \"南宁\"\n    },\n    {\n        id: \"2\",\n        title: \"避雷！！！大理古城天价露天停车场\",\n        content: \"本来在大理开开心心的游玩这么多天了，今天去往古城按照导航推荐的停车场停车。开始以为是个很正常的停车场，结果停完才发现10块钱一个小时！！！（气坏了！！！）大家赶紧赶紧避雷掉。我前一个车交完费显示35元，我还以为他停了很久，按照10块一小时停下去，无厘头的计费标准，拉低大理城市印象...\",\n        author: \"Double O seven\",\n        likes: 36,\n        collects: 197,\n        publishTime: \"2024-01-14\",\n        tags: [\n            \"大理古城\",\n            \"停车场\",\n            \"避坑指南\",\n            \"停车收费\"\n        ],\n        imageUrl: \"https://images.unsplash.com/photo-1548013146-724ded68c30d?w=400&h=300&fit=crop\",\n        location: \"大理\"\n    },\n    {\n        id: \"3\",\n        title: \"大理洱海西线一日游路线（骑电动\\uD83D\\uDEF5打卡版）\",\n        content: \"去了两次云南，总结出了这份大理一日游最佳路线✅建议你直接码住❗️第一次遇到好天气洱海、雪山\\uD83C\\uDFD4️、虎跳峡巨美让我想再去一次。租电动车\\uD83D\\uDEF525\\uD83D\\uDCB0一人，提前跟老板讲好第二天要看日出，提前一晚取车。大理环洱海我之前走过，真的很累。时间短的话我推荐大理古城这边的海西线，景点多，拍照\\uD83D\\uDCF7更加出片...\",\n        author: \"小T爱旅行\",\n        likes: 2551,\n        collects: 75,\n        publishTime: \"2024-01-13\",\n        tags: [\n            \"洱海\",\n            \"骑行\",\n            \"小众机位\",\n            \"大理攻略\"\n        ],\n        imageUrl: \"https://images.unsplash.com/photo-1506905925346-b28f40a0ca4b?w=400&h=300&fit=crop\",\n        location: \"洱海\"\n    },\n    {\n        id: \"4\",\n        title: \"替你们试过了 洱海骑行不踩雷攻略‼️\",\n        content: \"\\uD83D\\uDFE0洱海分洱东和洱西，洱西有生态廊道，生态廊道内只能骑自行车或者用区域内的共享电动车，可以直接从龙龛码头骑到喜洲。我们住才村，步行到才村码头只要几分钟，码头有很多租自行车的。推荐骑共享电动车（我们骑的小橙）15r/h，可以骑到喜洲古镇附近，也能临时锁车...\",\n        author: \"你今天真好看\",\n        likes: 1086,\n        collects: 123,\n        publishTime: \"2024-01-12\",\n        tags: [\n            \"洱海\",\n            \"骑行攻略\",\n            \"生态廊道\",\n            \"避坑指南\"\n        ],\n        imageUrl: \"https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=400&h=300&fit=crop\",\n        location: \"洱海\"\n    },\n    {\n        id: \"5\",\n        title: \"大理洱海生态廊道租车！全攻略！！\",\n        content: \"洱海生态廊道（海西）全长46公里，阳南溪(廊道起点)→桃源码头(廊道终点)，沿路每个村子都设置廊道关卡，外面租的自行车/电动车/汽车进不了廊道，所以看不到洱海。可以直接打车到沿途村子，进廊道内骑行或坐观光车游玩。共享单车预付\\uD83D\\uDCB030，前15min：\\uD83D\\uDCB02，15min后：\\uD83D\\uDCB01.5/15min...\",\n        author: \"中旅丨游大理\",\n        likes: 2276,\n        collects: 314,\n        publishTime: \"2024-01-11\",\n        tags: [\n            \"洱海生态廊道\",\n            \"租车攻略\",\n            \"交通攻略\",\n            \"官方攻略\"\n        ],\n        imageUrl: \"https://images.unsplash.com/photo-1449824913935-59a10b8d2000?w=400&h=300&fit=crop\",\n        location: \"洱海\"\n    },\n    {\n        id: \"6\",\n        title: \"亲测：玉龙雪山抢票攻略\\uD83C\\uDFAB冰川公园大索道\\uD83D\\uDEA0\",\n        content: \"看大家都说票很难抢要报旅行团，我想说真的不难抢\\uD83E\\uDDCF\\uD83C\\uDFFB‍♂️按照这篇攻略一步步来很大概率能抢到的\\uD83D\\uDE03在小红书上做了攻略之后两次抢票都丝滑抢到，因此总结一下经验，希望帮助即将要抢票的盆友们\\uD83D\\uDC6B首先玉龙雪山包含大中小索道，大索道可以坐索道上到4506高度，天气好的话可以通过步行栈道走到4680...\",\n        author: \"改改漂流记\",\n        likes: 1353,\n        collects: 101,\n        publishTime: \"2024-01-10\",\n        tags: [\n            \"玉龙雪山\",\n            \"抢票攻略\",\n            \"冰川公园\",\n            \"大索道\"\n        ],\n        imageUrl: \"https://images.unsplash.com/photo-1506905925346-b28f40a0ca4b?w=400&h=300&fit=crop\",\n        location: \"玉龙雪山\"\n    },\n    {\n        id: \"7\",\n        title: \"玉龙雪山\\uD83C\\uDFD4️自驾丽江\",\n        content: \"买票\\uD83C\\uDFAB在微信搜索：丽江旅游集团的官方小程序。定闹钟前一天20:00开始抢冰川公园索道票（大索道/140元），21:00抢牦牛坪索道票（中索道/65元）和云杉坪索道/60元。提前进入然后输入好验证码，20:00点一到就开抢。当天行程⏰我们只买了140元的冰川公园大索道，包含里面的大巴和蓝月谷...\",\n        author: \"张 小张\",\n        likes: 112,\n        collects: 17,\n        publishTime: \"2024-01-09\",\n        tags: [\n            \"玉龙雪山\",\n            \"自驾攻略\",\n            \"抢票攻略\",\n            \"丽江旅游\"\n        ],\n        imageUrl: \"https://images.unsplash.com/photo-1506905925346-b28f40a0ca4b?w=400&h=300&fit=crop\",\n        location: \"玉龙雪山\"\n    },\n    {\n        id: \"8\",\n        title: \"丽江玉龙雪山抢票攻略\",\n        content: \"决定去丽江的开始就马不停蹄在小红书上做功课，满是7、8月旺季抢不到玉龙雪山索道票的帖子，研究了一下终于摸清抢票套路。1.抢票小程序：丽江旅游集团。2.抢票开始时间，雪山索道票是提前7天的晚上20:00，云杉坪、牦牛坪是21:00。比如今天8-7，抢的是8-14的票，以此类推...\",\n        author: \"liz\",\n        likes: 875,\n        collects: 126,\n        publishTime: \"2024-01-08\",\n        tags: [\n            \"玉龙雪山\",\n            \"抢票攻略\",\n            \"丽江旅游\",\n            \"旺季攻略\"\n        ],\n        imageUrl: \"https://images.unsplash.com/photo-1449824913935-59a10b8d2000?w=400&h=300&fit=crop\",\n        location: \"玉龙雪山\"\n    },\n    {\n        id: \"9\",\n        title: \"云南大理自驾｜大理古城找停车场\\uD83C\\uDD7F️攻略！\",\n        content: \"这次是第四次自驾游来大理古城游玩，自驾游的痛点就是找停车场。由于古城、进出客栈的道路特别窄，很多都是单边通行，车技不好的要么刮车，要么开进去出不来。古城周边都是不能乱停车，有违停拍照\\uD83D\\uDCF7，能找到画格子的地方已经离古城偏远了，\\uD83D\\uDC49例如:大理大学附近...\",\n        author: \"仍活着到处走\",\n        likes: 734,\n        collects: 42,\n        publishTime: \"2024-01-07\",\n        tags: [\n            \"大理自驾\",\n            \"停车场攻略\",\n            \"古城停车\",\n            \"自驾游\"\n        ],\n        imageUrl: \"https://images.unsplash.com/photo-1506905925346-b28f40a0ca4b?w=400&h=300&fit=crop\",\n        location: \"大理\"\n    },\n    {\n        id: \"10\",\n        title: \"花了几个小时做的南宁美食攻略，请本地人来\",\n        content: \"帮我喵一眼吧，后续打算在这些店里选择位置合适的，或者随机选择了。请南宁的uu帮忙看看有没有那些需要排雷的？或者有其他的种草的也可以。老表记螺丝鸭脚煲、桂花烤排骨、生烤牛肉、黄油啤酒都没有踩雷，甚至有再去吃一次的想法，可以冲...\",\n        author: \"是歪歪呀！\",\n        likes: 4015,\n        collects: 582,\n        publishTime: \"2024-01-06\",\n        tags: [\n            \"南宁美食\",\n            \"美食攻略\",\n            \"本地人推荐\",\n            \"美食探店\"\n        ],\n        imageUrl: \"https://images.unsplash.com/photo-1506905925346-b28f40a0ca4b?w=400&h=300&fit=crop\",\n        location: \"南宁\"\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./data/xiaohongshuData.ts\n");

